import {SUITS,ENEMIES,RELICS,newRun,restore,preview,intent,toggle,move,redraw,attack,chooseReward} from './engine.js';
const $=id=>document.getElementById(id),KEY='mimics-hand-forest-v1';
let saved=null;try{saved=restore(JSON.parse(localStorage.getItem(KEY)));}catch{}
let state=saved||newRun(),busy=false,sound=false,audio,lastFrame=0,pose=0,poseUntil=0,enemyShake=0,heroShake=0,particles=[],actionKey=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('save-status').textContent='Progress saved on this device';}catch{$('save-status').textContent='Progress lasts for this session';}}
function caption(text){$('battle-caption').textContent=text;}
function render(){
  $('your-hp').textContent=`${state.hp} / ${state.maxHp} HP`;$('your-health').style.width=`${state.hp/state.maxHp*100}%`;$('enemy-name').textContent=state.enemy.name;$('enemy-role').textContent=state.enemy.role;$('enemy-hp').textContent=`${state.enemy.hp} / ${state.enemy.maxHp} HP`;$('enemy-health').style.width=`${state.enemy.hp/state.enemy.maxHp*100}%`;$('turn').textContent=`TURN ${state.turn}`;$('gold').textContent=state.gold;$('relic-count').textContent=state.relics.length;$('intent').textContent=intent(state).label;$('poison').textContent=state.poison?`${state.poison} poison remaining`:'';
  $('route').replaceChildren();ENEMIES.forEach((enemy,i)=>{const el=document.createElement('div');el.className='route-step'+(i===state.stage?' active':i<state.stage?' done':'');el.innerHTML=`<b>${i<state.stage?'✓':i===4?'♜':i+1}</b><span>${enemy.name.replace('The ','')}</span>`;if(i===state.stage)el.setAttribute('aria-current','step');$('route').append(el);});
  const plan=preview(state);$('chain').replaceChildren();for(let i=0;i<5;i++){const step=plan.steps[i],el=document.createElement('div');el.className='chain-slot'+(step?' filled':'')+(step?.linked?' linked':'');if(step){el.style.setProperty('--suit',SUITS[step.suit].color);el.innerHTML=`<span class="order">${i+1}</span><span class="mini-symbol">${SUITS[step.suit].symbol}</span><b>${step.rank}</b><span class="multi">×${step.multiplier.toFixed(2)}</span>`;const reorder=document.createElement('div');reorder.className='reorder';for(const [direction,label]of [[-1,'←'],[1,'→']]){const button=document.createElement('button');button.textContent=label;button.setAttribute('aria-label',`Move card ${i+1} ${direction<0?'earlier':'later'}`);button.disabled=busy||state.phase!=='battle'||i+direction<0||i+direction>=state.selected.length;button.onclick=()=>{if(busy)return;move(state,i,direction);render();save();};reorder.append(button);}el.append(reorder);}else el.textContent=i+1;$('chain').append(el);}
  const netDamage=Math.max(0,plan.damage-intent(state).guard),predictedReturn=netDamage+state.poison+plan.poison>=state.enemy.hp?0:Math.max(0,intent(state).damage-plan.block);$('preview').innerHTML=`<span title="${plan.damage} raw damage, ${intent(state).guard} enemy armor"><b>${netDamage}</b> damage</span><span><b>${plan.block}</b> armor</span><span><b>${plan.heal}</b> heal</span><span><b>${plan.poison}</b> poison</span><span title="Expected enemy damage after your armor"><b>${predictedReturn}</b> return</span>`;$('attack').disabled=busy||state.phase!=='battle'||!state.selected.length;$('redraw').disabled=busy||state.phase!=='battle'||!state.redraws||!state.selected.length;$('redraw-count').textContent=state.redraws;$('clear').disabled=busy||!state.selected.length;$('deck-count').textContent=`${state.deck.length} draw · ${state.discard.length} discard`;
  $('hand').replaceChildren();state.hand.forEach((card,i)=>{const suit=SUITS[card.suit],order=state.selected.indexOf(card.id);const button=document.createElement('button');button.className='card'+(order>=0?' selected':'');button.style.setProperty('--suit',suit.color);button.disabled=busy||state.phase!=='battle';button.setAttribute('aria-pressed',order>=0);button.setAttribute('aria-label',`${suit.name} ${card.rank}, ${suit.effect}${order>=0?`, selected ${order+1}`:''}`);button.innerHTML=`<span class="card-rank">${card.rank}</span><span class="card-symbol">${suit.symbol}</span><span class="card-name">${suit.name}</span><span class="card-effect">${suit.effect}</span>${order>=0?`<span class="selected-number">${order+1}</span>`:''}`;button.onclick=()=>select(card.id);$('hand').append(button);});
  $('relics').replaceChildren();if(!state.relics.length)$('relics').textContent='Nothing but rusty hinges. For now.';for(const id of state.relics){const relic=RELICS.find(r=>r.id===id),el=document.createElement('span');el.className='relic-pill';el.textContent=`${relic.symbol} ${relic.name}`;el.title=relic.description;$('relics').append(el);}
  $('log').replaceChildren();for(const line of state.log){const el=document.createElement('div');el.textContent=line;$('log').append(el);}renderOutcome();
}
function select(id){if(busy||state.phase!=='battle')return;toggle(state,id);tone(260+state.selected.length*60,.04);render();save();}
function renderOutcome(){const visible=!busy&&state.phase!=='battle';$('outcome').hidden=!visible;if(!visible)return;$('rewards').replaceChildren();if(state.phase==='reward'){
  $('outcome-tag').textContent='A FULL STOMACH. A NEW TRICK.';$('outcome-title').textContent='A delicious discovery.';$('outcome-copy').textContent=`+${state.enemy.reward} gold · +10 HP. Choose a relic for this run, or recover 15 more health.`;const available=RELICS.filter(r=>!state.relics.includes(r.id));const offset=state.stage%Math.max(1,available.length),choices=[...available.slice(offset),...available.slice(0,offset)].slice(0,2);for(const relic of [...choices,{id:'rest',name:'Catch your breath',symbol:'♡',description:'Recover 15 additional health.'}]){const button=document.createElement('button');button.className='reward-button';button.innerHTML=`<span>${relic.symbol}</span><b>${relic.name}</b><small>${relic.description}</small>`;button.onclick=()=>{if(chooseReward(state,relic.id)){particles=[];pose=0;caption(`Here comes ${state.enemy.name.toLowerCase()}. Read their next move.`);render();save();}};$('rewards').append(button);}
  }else{$('outcome-tag').textContent=state.phase==='won'?'CHAPTER I COMPLETE':'NOT EVERY MEAL IS AN EASY ONE';$('outcome-title').textContent=state.phase==='won'?'The forest is yours.':'Splinters and second chances.';$('outcome-copy').textContent=state.phase==='won'?`Five visitors devoured. ${state.gold} gold collected. Beyond the clearing, the old ruins await…`:`You reached encounter ${state.stage+1} and collected ${state.gold} gold. Try longer links, Shell armor, and timely healing.`;const button=document.createElement('button');button.className='primary';button.textContent=state.phase==='won'?'PLAY FOREST EDGE AGAIN ↗':'TRY AGAIN ↗';button.onclick=restart;$('rewards').append(button);}
}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function play(){if(busy||state.phase!=='battle'||!state.selected.length)return;busy=true;const report=attack(state),serial=++actionKey;save();render();for(const [index,step]of report.steps.entries()){if(serial!==actionKey)return;pose=2;poseUntil=performance.now()+210;enemyShake=performance.now()+180;particles.push({x:645+Math.random()*35,y:228-index*6,text:`${step.damage}`,color:SUITS[step.suit].color,born:performance.now()});caption(`${SUITS[step.suit].name} ${step.rank} → ×${step.multiplier.toFixed(2)}${step.linked?' · LINKED!':''}`);tone(320+index*80,.08);await wait(reduced?30:260);}if(report.poisonDamage){particles.push({x:665,y:220,text:`${report.poisonDamage} poison`,color:'#b191d0',born:performance.now()});await wait(reduced?30:220);}if(report.incoming){pose=3;poseUntil=performance.now()+550;heroShake=performance.now()+300;particles.push({x:290,y:220,text:`−${report.incoming}`,color:'#f1c4a8',born:performance.now()});tone(130,.12);}else if(!report.killed&&report.block){particles.push({x:300,y:220,text:'BLOCKED',color:'#bde1d7',born:performance.now()});}busy=false;caption(report.killed?`${state.enemy.name} devoured. The forest holds another meal.`:`${report.hit} bite damage${report.poisonDamage?` + ${report.poisonDamage} poison`:''}. ${report.incoming?`You took ${report.incoming} damage.`:'Their attack was blocked.'}`);render();save();}
function restart(){actionKey++;busy=false;state=newRun();particles=[];pose=0;caption('That chest definitely wasn’t here yesterday.');$('confirm').close();$('intro').close();render();save();}
$('attack').onclick=play;$('redraw').onclick=()=>{if(busy)return;if(redraw(state)){caption('Fresh cards. Fresh possibilities.');render();save();}};$('clear').onclick=()=>{if(busy)return;state.selected=[];render();save();};$('how').onclick=()=>$('help').showModal();$('close-help').onclick=()=>$('help').close();$('restart').onclick=()=>{if(!busy)$('confirm').showModal();};$('cancel-restart').onclick=()=>$('confirm').close();$('confirm-restart').onclick=restart;$('begin').onclick=()=>{$('intro').close();save();};$('log-toggle').onclick=()=>{$('log').hidden=!$('log').hidden;$('log-toggle').textContent=$('log').hidden?'Battle log ▾':'Battle log ▴';};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',sound);if(sound)tone(440,.08);};
document.addEventListener('keydown',event=>{if(document.querySelector('dialog[open]')||busy||event.repeat||event.ctrlKey||event.metaKey||event.altKey)return;const index=Number(event.key)-1;if(index>=0&&index<8){event.preventDefault();if(state.hand[index])select(state.hand[index].id);}else if(event.key==='Enter'&&document.activeElement===document.body){event.preventDefault();play();}else if(event.key.toLowerCase()==='r'){event.preventDefault();$('redraw').click();}else if(event.key==='Escape')$('clear').click();});
function tone(freq,duration){if(!sound)return;try{audio??=new AudioContext();audio.resume();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='triangle';oscillator.frequency.value=freq;gain.gain.setValueAtTime(.045,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);oscillator.connect(gain).connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+duration);}catch{}}
const canvas=$('world'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;const forest=new Image(),mimic=new Image(),visitors=new Image();forest.src='assets/forest.png';mimic.src='assets/mimic.png';visitors.src='assets/visitors.png';
function sprite(image,sx,sy,sw,sh,x,y,w,h){if(image.complete&&image.naturalWidth)ctx.drawImage(image,sx,sy,sw,sh,x,y,w,h);}
function draw(time){requestAnimationFrame(draw);if(time-lastFrame<33)return;lastFrame=time;ctx.fillStyle='#789960';ctx.fillRect(0,0,960,420);if(forest.complete&&forest.naturalWidth){const cropHeight=forest.naturalWidth*420/960;ctx.drawImage(forest,0,120,forest.naturalWidth,cropHeight,0,0,960,420);}if(time>poseUntil)pose=busy?1:0;const bob=reduced?0:Math.sin(time/650)*2;const heroOffset=!reduced&&time<heroShake?Math.sin(time/18)*6:!reduced&&busy?8:0,enemyOffset=!reduced&&time<enemyShake?Math.sin(time/18)*5:0;
  ctx.fillStyle='#28402e55';ctx.beginPath();ctx.ellipse(300,316,72,12,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(665,316,38,9,0,0,Math.PI*2);ctx.fill();
  if(mimic.naturalWidth){const w=mimic.naturalWidth/2,h=mimic.naturalHeight/2;sprite(mimic,pose%2*w,Math.floor(pose/2)*h,w,h,160+heroOffset,145+bob,280,187);}else{ctx.fillStyle='#69564a';ctx.fillRect(231,223,138,75);}
  if(visitors.naturalWidth){const w=visitors.naturalWidth/5,h=visitors.naturalHeight;sprite(visitors,state.stage*w,0,w,h,605+enemyOffset,134+bob,125,210);}else{ctx.fillStyle='#b3a07b';ctx.fillRect(640,224,38,70);}
  for(let i=0;i<7;i++){const x=(time/40+i*153)%960,y=165+(i*29)%190;ctx.fillStyle='#edf4b6';ctx.globalAlpha=.2+Math.sin(time/500+i)*.2;ctx.fillRect(reduced?i*120+40:x,y,2,2);}ctx.globalAlpha=1;
  particles=particles.filter(p=>time-p.born<1000);for(const p of particles){const age=time-p.born;ctx.globalAlpha=Math.max(0,1-age/1000);ctx.font='bold 24px monospace';ctx.textAlign='center';ctx.lineWidth=4;ctx.strokeStyle='#20382c';ctx.strokeText(p.text,p.x,p.y-age/35);ctx.fillStyle=p.color;ctx.fillText(p.text,p.x,p.y-age/35);}ctx.globalAlpha=1;ctx.textAlign='start';
}
render();requestAnimationFrame(draw);if(!saved)$('intro').showModal();
